package pt.realmcouncil.domain;

import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static pt.realmcouncil.domain.CouncilState.*;

class CouncilStateTest {
    static final long NOW=1000000;
    static final UUID A=new UUID(0,1),B=new UUID(0,2),C=new UUID(0,3),D=new UUID(0,4);
    CouncilState s;
    @BeforeEach void setup(){s=new CouncilState();for(var id:List.of(A,B,C,D))s.observe(id,"Player"+id.getLeastSignificantBits(),2400,NOW-1);}
    Election create(){return s.create("Realm Governor",NOW,1000,1000,1000,10000,1000,0,1,16,3);}
    void nominate(UUID id){s.nominate(id,new Identity("Name"+id.getLeastSignificantBits(),"Elfo",24,true),"A better realm","sun","Build a market and improve roads.",NOW+1);}
    Election ballot(){var e=create();nominate(A);nominate(B);s.tick(NOW+2000);return e;}
    void vote(UUID player,UUID choice){s.cast(player,s.current.id,s.current.round,choice,NOW+2100);}
    void winner(){ballot();vote(A,A);vote(B,A);s.tick(NOW+3000);}
    @Test void electoralRollIsFixedAndHasTheExactPlayTimeThreshold(){var e=s.create("Governor",NOW,1000,1000,1000,10000,1000,2400,1,16,3);assertEquals(Set.of(A,B,C,D),e.eligible);var newcomer=new UUID(0,5);s.observe(newcomer,"Newcomer",5000,NOW+2);assertFalse(e.eligible.contains(newcomer));}
    @Test void operatorsCanEnrolOnlyDuringNominations(){create();var newcomer=new UUID(0,5);s.observe(newcomer,"Newcomer",0,NOW+2);s.enrol(newcomer);assertTrue(s.current.eligible.contains(newcomer));s.tick(NOW+1000);assertThrows(Rules.RuleException.class,()->s.enrol(C));}
    @Test void candidatesKeepCanonicalRpIdentity(){create();nominate(A);var c=s.current.candidates.get(A);assertEquals("Name1",c.name());assertEquals("Elfo",c.race());assertTrue(c.roleplay());assertEquals("Player1",c.minecraftName());}
    @Test void existingCandidateMayEditDuringCampaignButNewCandidatesCannot(){create();nominate(A);s.tick(NOW+1000);s.nominate(A,new Identity("Name1","Elfo",24,true),"Updated campaign","moon","A revised programme for the realm.",NOW+1100);assertEquals("moon",s.current.candidates.get(A).symbol());assertThrows(Rules.RuleException.class,()->s.nominate(B,new Identity("B","",0,false),"New campaign","sun","A programme for the realm.",NOW+1100));}
    @Test void candidatureLimitsAreEnforcedWithoutReplacingOtherCandidates(){s.create("Governor",NOW,1000,1000,1000,10000,1000,0,1,1,3);nominate(A);assertThrows(Rules.RuleException.class,()->nominate(B));assertEquals(1,s.current.candidates.size());}
    @Test void candidatureFieldsRejectControlsAndUnknownSymbols(){create();assertThrows(Rules.RuleException.class,()->s.nominate(A,new Identity("A","",0,false),"Bad\u00a7a title","sun","A proposal for the realm",NOW));assertThrows(Rules.RuleException.class,()->s.nominate(A,new Identity("A","",0,false),"Valid title","../../evil","A proposal for the realm",NOW));assertTrue(s.current.candidates.isEmpty());}
    @Test void withdrawalIsAllowedBeforeVotingAndRejectedAfterwards(){create();nominate(A);s.tick(NOW+1000);s.withdraw(A,NOW+1100);assertTrue(s.current.candidates.isEmpty());nominateDuringInvalidPhase();}
    void nominateDuringInvalidPhase(){assertThrows(Rules.RuleException.class,()->nominate(B));}
    @Test void nominationIsLockedDuringVoting(){ballot();assertThrows(Rules.RuleException.class,()->s.nominate(A,new Identity("A","",0,false),"Valid title","sun","A proposal for the realm",NOW+2100));assertThrows(Rules.RuleException.class,()->s.withdraw(A,NOW+2100));}
    @Test void votesRequireVotingPhase(){var e=create();nominate(A);assertThrows(Rules.RuleException.class,()->s.cast(A,e.id,1,A,NOW+100));assertTrue(e.ballots.isEmpty());}
    @Test void duplicateVoteDoesNotAlterOriginalChoice(){ballot();vote(A,A);assertThrows(Rules.RuleException.class,()->vote(A,B));assertEquals(A.toString(),s.current.ballots.get(A));}
    @Test void blankVotesCountAsParticipation(){ballot();vote(A,null);vote(B,A);s.tick(NOW+3000);var result=s.current.results.getFirst();assertEquals(2,result.turnout());assertEquals(1,result.blank());assertEquals(1,result.counts().get(A));assertEquals(A,s.current.winner);}
    @Test void aCandidateCanVoteForThemself(){ballot();vote(A,A);s.tick(NOW+3000);assertEquals(A,s.current.winner);}
    @Test void invalidCandidateAndIneligibleVoterLeaveBallotsUnchanged(){ballot();assertThrows(Rules.RuleException.class,()->vote(new UUID(0,9),A));assertThrows(Rules.RuleException.class,()->vote(A,C));assertTrue(s.current.ballots.isEmpty());}
    @Test void staleElectionAndRoundRequestsAreRejected(){var e=ballot();assertThrows(Rules.RuleException.class,()->s.cast(A,UUID.randomUUID(),1,A,NOW+2100));assertThrows(Rules.RuleException.class,()->s.cast(A,e.id,2,A,NOW+2100));assertTrue(e.ballots.isEmpty());}
    @Test void tieStartsAnotherRoundWithFreshBallotsAndOnlyTiedCandidates(){create();nominate(A);nominate(B);nominate(C);s.tick(NOW+2000);vote(A,A);vote(B,B);s.tick(NOW+3000);assertEquals(Phase.RUNOFF,s.current.phase);assertEquals(2,s.current.round);assertEquals(Set.of(A,B),s.current.contenders);assertTrue(s.current.ballots.isEmpty());assertThrows(Rules.RuleException.class,()->s.cast(C,s.current.id,2,C,NOW+3100));s.cast(A,s.current.id,2,B,NOW+3100);s.tick(NOW+4000);assertEquals(B,s.current.winner);}
    @Test void persistentTieEndsWithoutRandomlyChoosingAWinner(){ballot();vote(A,A);vote(B,B);s.tick(NOW+3000);for(int round=2;round<=3;round++){long time=NOW+3000+(round-2)*1000;s.cast(A,s.current.id,round,A,time+1);s.cast(B,s.current.id,round,B,time+1);s.tick(time+1000);}assertEquals("tie_limit",s.current.outcome);assertNull(s.current.winner);assertNull(s.mandate);}
    @Test void quorumFailureProducesNoMandate(){s.create("Governor",NOW,1000,1000,1000,10000,1000,0,3,16,3);nominate(A);s.tick(NOW+2000);vote(A,A);s.tick(NOW+3000);assertEquals("turnout",s.current.outcome);assertNull(s.mandate);}
    @Test void allBlankVotesCannotElectSomeone(){ballot();vote(A,null);vote(B,null);s.tick(NOW+3000);assertEquals("no_support",s.current.outcome);assertNull(s.mandate);}
    @Test void offlineDeadlineProgressionClosesAnEmptyElection(){create();assertTrue(s.tick(NOW+50000));assertEquals("no_candidates",s.current.outcome);assertEquals(Phase.FINISHED,s.current.phase);}
    @Test void winnerReceivesExactlyOneTermWithConfiguredDuration(){winner();assertEquals(A,s.mandate.playerId);assertEquals(NOW+3000,s.mandate.beginsAt);assertEquals(NOW+13000,s.mandate.endsAt);assertFalse(s.tick(NOW+6000));assertEquals(NOW+13000,s.mandate.endsAt);}
    @Test void oathIsRestrictedToTheWinnerAndCannotBeRepeated(){winner();assertThrows(Rules.RuleException.class,()->s.claim(B,NOW+3100));s.claim(A,NOW+3100);assertEquals(NOW+3100,s.mandate.claimedAt);assertThrows(Rules.RuleException.class,()->s.claim(A,NOW+3200));}
    @Test void publicDecisionsRequireAnActiveSwornMandate(){winner();assertThrows(Rules.RuleException.class,()->s.publish(A,"A new public market will be built.",NOW+3100));s.claim(A,NOW+3100);assertThrows(Rules.RuleException.class,()->s.publish(B,"A new public market will be built.",NOW+3200));s.publish(A,"A new public market will be built.",NOW+3200);assertEquals(1,s.mandate.decisions.size());assertThrows(Rules.RuleException.class,()->s.publish(A,"A new public market will be built.",NOW+13000));}
    @Test void newElectionsCannotOverlapAnActiveTerm(){winner();assertThrows(Rules.RuleException.class,this::create);s.endTerm(NOW+3100);s.create("Next Governor",NOW+3200,1000,1000,1000,10000,1000,0,1,16,3);assertEquals(1,s.history.size());}
    @Test void activeElectionCannotBeOverwritten(){create();assertThrows(Rules.RuleException.class,this::create);assertEquals("Realm Governor",s.current.title);}
    @Test void cancellationPreservesItsRecordAndAllowsAnotherElection(){create();nominate(A);s.cancel(NOW+500);assertEquals(Phase.CANCELLED,s.current.phase);create();assertEquals(1,s.history.size());assertEquals("cancelled",s.history.getFirst().outcome);}
    @Test void manualAdvancementRetainsFullRemainingPhaseDurations(){create();s.advance(NOW+100);assertEquals(NOW+1100,s.current.campaignEnd);assertEquals(NOW+2100,s.current.votingEnd);s.advance(NOW+200);assertEquals(NOW+1200,s.current.votingEnd);assertEquals(Phase.VOTING,s.current.phase);}
    @Test void restartPreservesVotesCandidaturesAndNoRepeatVoting(){ballot();vote(C,A);String json=s.toJson();s=CouncilState.fromJson(json);assertEquals(A.toString(),s.current.ballots.get(C));assertEquals("Elfo",s.current.candidates.get(A).race());assertThrows(Rules.RuleException.class,()->vote(C,B));s.tick(NOW+3000);assertEquals(A,s.mandate.playerId);}
    @Test void publicProjectionDoesNotExposeIndividualBallotsOrVoterIdentities(){ballot();vote(C,A);String json=CouncilState.JSON.toJson(CouncilView.of(s,D,new Identity("D","",0,false),false,"board",NOW+2200,120));assertFalse(json.contains("ballots"));assertFalse(json.contains(C.toString()));assertFalse(json.contains("\"eligible\":["));assertFalse(json.contains("counts"));assertTrue(json.contains("\"turnout\":1"));}
    @Test void storageRejectsForgedVotesAndUnknownSchema(){ballot();s.current.ballots.put(C,new UUID(0,99).toString());assertThrows(Rules.RuleException.class,()->CouncilState.fromJson(s.toJson()));s.current.ballots.clear();s.schema=8;assertThrows(Rules.RuleException.class,()->CouncilState.fromJson(s.toJson()));}
    @Test void historicalStorageIsBoundedAndPublicHistoryIsNewestFirst(){for(int i=0;i<24;i++){s.create("Election "+i,NOW+i,1000,1000,1000,10000,1000,0,1,16,3);s.cancel(NOW+i);}assertEquals(20,s.history.size());var v=CouncilView.of(s,A,new Identity("A","",0,false),false,"remote",NOW+30,120);assertEquals(10,v.history().size());assertEquals("Election 22",v.history().getFirst().title());}
    @Test void randomizedRoundsConserveEveryRecordedBallot(){var r=new Random(815);for(int test=0;test<500;test++){setup();ballot();int blanks=0,a=0,b=0;for(UUID voter:List.of(A,B,C,D)){int choice=r.nextInt(3);vote(voter,choice==0?null:choice==1?A:B);if(choice==0)blanks++;else if(choice==1)a++;else b++;}s.tick(NOW+3000);var result=s.current.results.getFirst();assertEquals(4,result.turnout());assertEquals(blanks,result.blank());assertEquals(a,result.counts().get(A));assertEquals(b,result.counts().get(B));assertEquals(result.turnout(),result.blank()+result.counts().values().stream().mapToInt(Integer::intValue).sum());}}
    @Test void standaloneIdentityCanNominateWithoutRpFields(){create();s.nominate(A,new Identity("Player1","",0,false),"A simple motto","tree","A programme for all Minecraft players.",NOW+1);var c=s.current.candidates.get(A);assertFalse(c.roleplay());assertEquals(0,c.age());assertEquals("Player1",c.name());}
    @Test void durationAndTextLimitsRejectInvalidValues(){assertThrows(Rules.RuleException.class,()->Rules.duration(0));assertThrows(Rules.RuleException.class,()->Rules.duration(525601));assertEquals(60000,Rules.duration(1));assertEquals("Descrição válida",Rules.text(" Descrição válida ",3,50,false));assertThrows(Rules.RuleException.class,()->Rules.text("bad\ntext",3,50,false));}
}
